    assert_eq!(candidate(vec!["a.b.c.d.e","f.g","h"], "."), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h']);
    assert_eq!(candidate(vec!["@start", "end@", "@both@"], "@"), vec!['start', 'end', 'both']);
    assert_eq!(candidate(vec!["###", "#foo#bar#", "###baz##"], "#"), vec!['foo', 'bar', 'baz']);
    assert_eq!(candidate(vec!["repeated..dots", "triple|||pipes", "quadruple@@@@at"], "."), vec!['repeated', 'dots', 'triple|||pipes', 'quadruple@@@@at']);
    assert_eq!(candidate(vec!["a@b@c@d", "e@f", "g@h@i@j@k"], "@"), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k']);
    assert_eq!(candidate(vec!["multiple.separators.in.one.string", "another|string|with|separators"], "."), vec!['multiple', 'separators', 'in', 'one', 'string', 'another|string|with|separators']);
    assert_eq!(candidate(vec!["complex@punctuation@marks", "@leading@", "@trailing@", "@@multiple@@@"], "@"), vec!['complex', 'punctuation', 'marks', 'leading', 'trailing', 'multiple']);
    assert_eq!(candidate(vec!["a.b.c.d", "e.f", "g.h.i.j.k"], "."), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k']);
    assert_eq!(candidate(vec!["end.with.dot.", ".start.with.dot", ".middle.dot."], "."), vec!['end', 'with', 'dot', 'start', 'with', 'dot', 'middle', 'dot']);
    assert_eq!(candidate(vec!["x##y##z", "##", "w####v"], "#"), vec!['x', 'y', 'z', 'w', 'v']);
    assert_eq!(candidate(vec!["|||abc|||", "def|||ghi|||", "|||jkl|||mno|||"], "|"), vec!['abc', 'def', 'ghi', 'jkl', 'mno']);
    assert_eq!(candidate(vec!["word", "anotherword", "yetanotherword"], "x"), vec!['word', 'anotherword', 'yetanotherword']);
    assert_eq!(candidate(vec!["........", "...", "."], "."), vec![]);
    assert_eq!(candidate(vec!["#example#test#case", "##", "no#separator"], "#"), vec!['example', 'test', 'case', 'no', 'separator']);
    assert_eq!(candidate(vec!["........"], "."), vec![]);
    assert_eq!(candidate(vec!["apple,banana,cherry", "date,elderberry", "fig,grape"], "), vec!['apple', 'banana', 'cherry', 'date', 'elderberry', 'fig', 'grape']);
    assert_eq!(candidate(vec!["..", "...", "...."], "."), vec![]);
    assert_eq!(candidate(vec!["|||||||"], "|"), vec![]);
    assert_eq!(candidate(vec!["abc.def.ghi", "jkl..mno", "pqr"], "."), vec!['abc', 'def', 'ghi', 'jkl', 'mno', 'pqr']);
    assert_eq!(candidate(vec!["nested#(separators)#inside#strings", "#multiple##hashes##here", "#no#trailing#hash"], "#"), vec!['nested', '(separators)', 'inside', 'strings', 'multiple', 'hashes', 'here', 'no', 'trailing', 'hash']);
    assert_eq!(candidate(vec!["multiple...dots","here||||are","pipes","and###hashes"], "."), vec!['multiple', 'dots', 'here||||are', 'pipes', 'and###hashes']);
    assert_eq!(candidate(vec!["a|b||c|||d||||e"], "|"), vec!['a', 'b', 'c', 'd', 'e']);
    assert_eq!(candidate(vec![",,apple,,,banana,,,","cherry,,,","date,"], "), vec!['apple', 'banana', 'cherry', 'date']);
    assert_eq!(candidate(vec!["@start@", "middle@", "@end"], "@"), vec!['start', 'middle', 'end']);
    assert_eq!(candidate(vec!["#a#b#c#d", "#e##f#", "g#h#i#"], "#"), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i']);
    assert_eq!(candidate(vec!["a.b.c.d.e", "f.g.h", "i.j.k.l"], "."), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l']);
    assert_eq!(candidate(vec!["a.b.c.d.e", "f.g.h", "i.j.k.l.m"], "."), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm']);
    assert_eq!(candidate(vec!["special$characters$@#|$|@$#|", "@|#$|$#@|", "|@#$#@$|"], "|"), vec!['special$characters$@#', '$', '@$#', '@', '#$', '$#@', '@#$#@$']);
    assert_eq!(candidate(vec!["foo$bar$baz", "qux$quux", "corge$grault$garply"], "$"), vec!['foo', 'bar', 'baz', 'qux', 'quux', 'corge', 'grault', 'garply']);
